content.css:
.hs-root {
  box-sizing: border-box;
  height: 100%;
  display: flex;
  flex-direction: column;
  padding: 4px 6px 24px 6px;
  background: var(--bf-bg);
  color: var(--bf-text);
  font-family: "Segoe UI", sans-serif;
  overflow: hidden;
  position: relative;
}
.hs-header {
  padding: 2px 4px 6px;
}
.hs-header .hs-title {
  font-weight: 600;
}
.hs-header .hs-subtitle {
  color: var(--bf-muted);
}
.hs-toolbar {
  display: flex;
  gap: 6px;
  align-items: center;
  padding: 2px 0 6px;
}
.hs-search {
  flex: 1;
  min-width: 0;
  height: 28px;
  box-sizing: border-box;
  padding: 0 8px;
  border: 1px solid var(--bf-rule);
  border-radius: 4px;
  background: var(--bf-surface);
  color: inherit;
  font: inherit;
}
.hs-search:focus-visible {
  outline: 2px solid #D97B29;
  outline-offset: 1px;
}
.hs-btns {
  display: inline-flex;
  gap: 4px;
}
.hs-btn {
  height: 28px;
  padding: 0 8px;
  border: 1px solid var(--bf-rule);
  border-radius: 4px;
  background: var(--bf-surface);
  color: inherit;
  font: inherit;
  cursor: pointer;
}
.hs-btn:hover {
  border-color: #E8612A;
}
.hs-btn:focus-visible {
  outline: 2px solid #D97B29;
  outline-offset: 1px;
}
.hs-body {
  flex: 1;
  min-height: 0;
  overflow: auto;
}
.hs-head,
.hs-row {
  display: grid;
  align-items: center;
  column-gap: 6px;
  padding: 0 6px;
}
.hs-head {
  position: sticky;
  top: 0;
  z-index: 1;
  background: var(--bf-band);
  color: #fff;
  min-height: 24px;
  font-size: 11px;
}
.hs-head-kpi {
  text-align: right;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.hs-row {
  border-bottom: 1px solid var(--bf-rule);
  border-left: 3px solid transparent;
  cursor: pointer;
}
.hs-row:hover {
  background: var(--bf-surface-alt);
}
.hs-row:focus-visible {
  outline: 2px solid #D97B29;
  outline-offset: -2px;
}
.hs-row.hs-row--sel {
  background: rgba(232, 97, 42, 0.12);
  border-left-color: #E8612A;
}
.hs-name {
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
}
.hs-label {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.hs-chev {
  width: 14px;
  flex: none;
  text-align: center;
  color: var(--bf-muted);
}
.hs-box {
  width: 14px;
  height: 14px;
  flex: none;
  box-sizing: border-box;
  border: 1px solid var(--bf-muted);
  border-radius: 3px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 11px;
  line-height: 1;
  color: #fff;
}
.hs-box.hs-box--on {
  background: #E8612A;
  border-color: #E8612A;
}
.hs-box.hs-box--part {
  background: #E8612A;
  border-color: #E8612A;
  opacity: 0.6;
}
.hs-slot {
  display: flex;
  justify-content: flex-end;
  align-items: center;
  min-width: 0;
}
.hs-cell {
  display: inline-flex;
  align-items: center;
  gap: 4px;
}
.hs-pill {
  padding: 1px 7px;
  border-radius: 10px;
  font-weight: 500;
  font-size: 0.92em;
}
.hs-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  display: inline-block;
}
.hs-num {
  font-variant-numeric: tabular-nums;
}
.hs-marker {
  font-size: 0.85em;
}
.hs-bar {
  width: 32px;
  height: 6px;
  border-radius: 3px;
  background: var(--bf-rule);
  overflow: hidden;
  display: inline-block;
}
.hs-bar-fill {
  display: block;
  height: 100%;
}
.hs-empty {
  padding: 16px;
  color: var(--bf-muted);
  text-align: center;
}
.hs-root.hs-narrow .hs-btns {
  display: none;
}
